"use client"

import * as React from "react"
import { AnimatePresence, motion, useMotionValue, useReducedMotion, useSpring, type MotionValue } from "motion/react"

import { cn } from "@/lib/utils"

type ScrollRailItem = {
  /** matches a `data-rail-id` on the element it points to */
  id: string
  title: string
  excerpt?: string
  /** optional group label shown in the hover preview */
  group?: string
}

type ScrollRailProps = Omit<React.ComponentProps<"nav">, "children"> & {
  items: ScrollRailItem[]
  /** the element that scrolls; leave it out to follow the page */
  container?: HTMLElement | null
  /** which edge of its content the rail sits on; the preview opens toward the content */
  side?: "left" | "right"
}

const TICK = 9
const REST = 8
const REACH = 56
const SWELL = 18
const RAIL_SPRING = { type: "spring" as const, stiffness: 300, damping: 34, mass: 0.8 }

// a quiet document minimap: every mark rests at the same short length, nearby marks swell toward
// the pointer, and the active mark brightens without changing size
function ScrollRail({ items, container = null, side = "right", className, onPointerMove, onPointerLeave, ...props }: ScrollRailProps) {
  const reduceMotion = useReducedMotion()
  const [active, setActive] = React.useState(0)
  const [hover, setHover] = React.useState<{ index: number; y: number } | null>(null)
  const pointerY = useMotionValue(Infinity)
  const buttons = React.useRef<(HTMLButtonElement | null)[]>([])
  const hideTimer = React.useRef(0)
  // the tick you clicked stays lit even if the content ends before that part can reach the top;
  // it lets go as soon as you scroll yourself
  const pinned = React.useRef<number | null>(null)

  const find = React.useCallback(
    (id: string) => (container ?? document).querySelector<HTMLElement>(`[data-rail-id="${CSS.escape(id)}"]`),
    [container]
  )

  // the current part is the last one whose top has passed a line near the top of the view, so the part
  // you just jumped to is the one that lights up
  React.useEffect(() => {
    let frame = 0
    pinned.current = null
    const measure = () => {
      frame = 0
      if (pinned.current !== null) {
        setActive(pinned.current)
        return
      }
      const top = container ? container.getBoundingClientRect().top : 0
      const height = container ? container.clientHeight : window.innerHeight
      const line = top + height * 0.15
      let next = 0
      items.forEach((item, index) => {
        const node = find(item.id)
        if (node && node.getBoundingClientRect().top <= line) next = index
      })
      const atEnd = container
        ? container.scrollTop + container.clientHeight >= container.scrollHeight - Math.max(24, height * 0.02)
        : window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - Math.max(24, height * 0.02)
      const atStart = container ? container.scrollTop <= 2 : window.scrollY <= 2
      setActive(atStart ? 0 : atEnd ? items.length - 1 : next)
    }
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure)
    }
    schedule()
    const scroller: HTMLElement | Window = container ?? window
    const release = () => {
      pinned.current = null
      schedule()
    }
    scroller.addEventListener("scroll", schedule, { passive: true })
    scroller.addEventListener("wheel", release, { passive: true })
    scroller.addEventListener("touchmove", release, { passive: true })
    scroller.addEventListener("pointerdown", release)
    window.addEventListener("keydown", release)
    window.addEventListener("resize", schedule)
    return () => {
      cancelAnimationFrame(frame)
      scroller.removeEventListener("scroll", schedule)
      scroller.removeEventListener("wheel", release)
      scroller.removeEventListener("touchmove", release)
      scroller.removeEventListener("pointerdown", release)
      window.removeEventListener("keydown", release)
      window.removeEventListener("resize", schedule)
    }
  }, [container, find, items])

  React.useEffect(() => () => window.clearTimeout(hideTimer.current), [])

  function show(index: number) {
    window.clearTimeout(hideTimer.current)
    const node = buttons.current[index]
    if (node) setHover({ index, y: node.offsetTop + node.offsetHeight / 2 })
  }

  function hideSoon() {
    window.clearTimeout(hideTimer.current)
    hideTimer.current = window.setTimeout(() => setHover(null), 120)
  }

  function go(index: number) {
    pinned.current = index
    setActive(index)
    const target = find(items[index].id)
    if (!target) return
    const behavior = reduceMotion ? "auto" : "smooth"
    if (container) {
      const delta = target.getBoundingClientRect().top - (container.getBoundingClientRect().top + 20)
      container.scrollTo({ top: container.scrollTop + delta, behavior })
    } else {
      target.scrollIntoView({ behavior, block: "start" })
    }
  }

  function onKeyDown(event: React.KeyboardEvent, index: number) {
    const to =
      event.key === "ArrowDown" || event.key === "ArrowRight"
        ? Math.min(index + 1, items.length - 1)
        : event.key === "ArrowUp" || event.key === "ArrowLeft"
          ? Math.max(index - 1, 0)
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? items.length - 1
              : null
    if (to === null) return
    event.preventDefault()
    buttons.current[to]?.focus()
  }

  const item = hover ? items[hover.index] : null

  return (
    <nav
      data-slot="scroll-rail"
      aria-label="Jump to"
      className={cn("relative w-10", className)}
      onPointerMove={(event) => {
        onPointerMove?.(event)
        pointerY.set(event.clientY)
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event)
        pointerY.set(Infinity)
        hideSoon()
      }}
      {...props}
    >
      <div className="relative flex flex-col" onPointerLeave={hideSoon}>
        {items.map((entry, index) => (
          <Tick
            key={entry.id}
            ref={(node) => {
              buttons.current[index] = node
            }}
            label={entry.title}
            side={side}
            active={index === active}
            pointerY={pointerY}
            onClick={() => go(index)}
            onPointerEnter={() => show(index)}
            onFocus={() => show(index)}
            onBlur={hideSoon}
            onKeyDown={(event) => onKeyDown(event, index)}
            tabIndex={index === active ? 0 : -1}
          />
        ))}

        <AnimatePresence>
          {hover && item && (
            <motion.div
              key="preview"
              aria-hidden
              className={cn("pointer-events-none absolute top-0 z-10 w-72", side === "right" ? "right-full mr-3" : "left-full ml-3")}
              style={{ transformOrigin: side === "right" ? "right center" : "left center" }}
              initial={{ opacity: 0, scale: 0.96, y: hover.y }}
              animate={{ opacity: 1, scale: 1, y: hover.y }}
              exit={{ opacity: 0, scale: 0.96, transition: { duration: 0.1 } }}
              transition={{
                opacity: { duration: 0.15 },
                scale: { type: "spring", duration: 0.25, bounce: 0 },
                y: reduceMotion ? { duration: 0 } : RAIL_SPRING,
              }}
            >
              <div className="-translate-y-1/2 rounded-[20px] bg-glass p-3.5 shadow-glass backdrop-blur-2xl backdrop-saturate-150">
                <div className="relative">
                  <AnimatePresence mode="popLayout" initial={false}>
                    <motion.div
                      key={hover.index}
                      initial={{ opacity: 0, y: reduceMotion ? 0 : 4 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, transition: { duration: 0.08 } }}
                      transition={{ duration: 0.15, ease: [0.2, 0.8, 0.2, 1] }}
                    >
                      <p className="text-[11px] text-foreground/50 tabular-nums">
                        {item.group ? `${item.group} · ` : ""}
                        {hover.index + 1} of {items.length}
                      </p>
                      <p className="mt-0.5 truncate text-sm font-medium text-foreground">{item.title}</p>
                      {item.excerpt && (
                        <p className="mt-1 line-clamp-2 text-[13px] leading-snug text-foreground/60">{item.excerpt}</p>
                      )}
                    </motion.div>
                  </AnimatePresence>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </nav>
  )
}

type TickProps = Omit<React.ComponentProps<"button">, "children"> & {
  label: string
  side: "left" | "right"
  active: boolean
  pointerY: MotionValue<number>
}

function Tick({ ref, label, side, active, pointerY, className, ...props }: TickProps) {
  const reduceMotion = useReducedMotion()
  const node = React.useRef<HTMLButtonElement | null>(null)
  const width = useSpring(REST, RAIL_SPRING)
  const opacity = useSpring(0.3, RAIL_SPRING)

  // swell with how near the pointer is, on top of the resting length
  React.useEffect(() => {
    const update = () => {
      const y = pointerY.get()
      let near = 0
      if (Number.isFinite(y) && node.current) {
        const rect = node.current.getBoundingClientRect()
        const proximity = Math.max(0, 1 - Math.abs(y - (rect.top + rect.height / 2)) / REACH)
        near = proximity * proximity * (3 - 2 * proximity)
      }
      const nextWidth = REST + SWELL * near
      const nextOpacity = active ? 0.78 : 0.22 + 0.48 * near
      if (reduceMotion) {
        width.jump(nextWidth)
        opacity.jump(nextOpacity)
      } else {
        width.set(nextWidth)
        opacity.set(nextOpacity)
      }
    }
    update()
    return pointerY.on("change", update)
  }, [active, opacity, pointerY, reduceMotion, width])

  return (
    <button
      ref={(element) => {
        node.current = element
        if (typeof ref === "function") ref(element)
        else if (ref) ref.current = element
      }}
      type="button"
      aria-label={label}
      aria-current={active ? "true" : undefined}
      className={cn(
        "group flex w-10 cursor-pointer items-center rounded-sm outline-none focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-ring",
        side === "right" ? "justify-end" : "justify-start",
        className
      )}
      style={{ height: TICK }}
      {...props}
    >
      <motion.span aria-hidden className="h-[2px] rounded-full bg-foreground" style={{ width, opacity }} />
    </button>
  )
}

export { ScrollRail, type ScrollRailItem, type ScrollRailProps }

import type { CSSProperties } from "react"
import type { TargetAndTransition, Transition } from "motion/react"

// shared spring presets, every component picks from these
export const springs = {
  snappy: { stiffness: 520, damping: 34, mass: 0.6 },
  soft: { stiffness: 260, damping: 26, mass: 0.8 },
  glide: { stiffness: 120, damping: 20, mass: 1 },
} as const

export type SpringName = keyof typeof springs

export function spring(name: SpringName): Transition {
  return { type: "spring", ...springs[name] }
}

// how a glow fades once its source moves away: slow, with a long tail
export const afterglow = {
  linger: 0.9,
  ease: [0.22, 1, 0.36, 1],
} as const satisfies { linger: number; ease: Transition["ease"] }

// paints only the padding ring of an element, used for glowing borders
export const ringMask: CSSProperties = {
  WebkitMask:
    "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  WebkitMaskComposite: "xor",
  mask: "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  maskComposite: "exclude",
}

// small icon gestures, played when a control is pressed or selected
export const iconGestures = {
  pop: { scale: [1, 1.2, 1] },
  ring: { rotate: [0, -18, 14, -9, 4, 0], scale: [1, 1.12, 1] },
  // a gear looks the same after half a turn, so it can rest there and snap back unseen
  turn: { rotate: [0, 180], scale: [1, 1.12, 1] },
  hop: { y: [0, -3, 0], scale: [1, 1.1, 1] },
  nudge: { x: [0, 2.5, 0], scale: [1, 1.1, 1] },
} satisfies Record<string, TargetAndTransition>

export type IconGesture = keyof typeof iconGestures

// leaving a gesture is instant: every gesture already ends at, or looks like, its resting pose
export const iconRest: TargetAndTransition = { scale: 1, rotate: 0, x: 0, y: 0, transition: { duration: 0 } }
